## Top 10 IaC Misconfigurations

### Terraform Examples

**1. Overly Permissive Security Groups**
```hcl
# ❌ DANGEROUS - Allows all traffic from anywhere
resource "aws_security_group" "open" {
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]  # Open to the world!
  }
}

# ✅ SECURE - Restrict to specific CIDR and port
resource "aws_security_group" "restricted" {
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]  # Internal only
  }
}
```

**2. Unencrypted Storage**
```hcl
# ❌ DANGEROUS - S3 bucket without encryption
resource "aws_s3_bucket" "data" {
  bucket = "my-sensitive-data"
  # Missing: server_side_encryption_configuration
}

# ✅ SECURE - Encryption enabled
resource "aws_s3_bucket_server_side_encryption_configuration" "data_enc" {
  bucket = aws_s3_bucket.data.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}
```

**3. Public S3 Buckets**
```hcl
# ❌ DANGEROUS
resource "aws_s3_bucket_acl" "public" {
  bucket = aws_s3_bucket.data.id
  acl    = "public-read"  # Publicly accessible!
}
```

**4. Hardcoded Secrets**
```hcl
# ❌ DANGEROUS - Secret in plain text
resource "aws_db_instance" "db" {
  password = "MyP@ssw0rd123"  # Hardcoded!
}

# ✅ SECURE - Reference from vault
resource "aws_db_instance" "db" {
  password = data.vault_generic_secret.db_creds.data["password"]
}
```

**5. Disabled Logging**
```hcl
# ❌ DANGEROUS - No CloudTrail or access logs
# Missing: aws_cloudtrail, aws_s3_bucket_logging

# ✅ SECURE - Enable logging
resource "aws_s3_bucket_logging" "data_logs" {
  bucket = aws_s3_bucket.data.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "log/"
}
```

